   - DateTime.fromISO("0099-12-31").plus({ day: 2 }).toISODate() === "0100-01-02"
   - DateTime.fromISO("0100-01-02").minus({ day: 2 }).toISODate() === "0099-12-31"
   - DateTime.fromISO("0001-01-01", { zone: "UTC" }).toISODate() === "0001-01-01"
